package com.bank.gateway.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Entity
@Table(name = "transactions")
public class Transaction {
    @Id @Column(name = "txn_id") private String txnId;
    @Column(name = "from_account") private String fromAccount;
    @Column(name = "to_account") private String toAccount;
    private BigDecimal amount;
    private String channel;
    private BigDecimal gst;
    private String status;
    @Column(name = "created_at") private LocalDateTime createdAt;

    protected Transaction() {}

    public Transaction(String txnId, String fromAccount, String toAccount,
                       BigDecimal amount, String channel, BigDecimal gst) {
        this.txnId = txnId;
        this.fromAccount = fromAccount;
        this.toAccount = toAccount;
        this.amount = amount;
        this.channel = channel;
        this.gst = gst;
        this.status = "PENDING";
        this.createdAt = LocalDateTime.now();
    }

    public String getTxnId() { return txnId; }
    public String getFromAccount() { return fromAccount; }
    public String getToAccount() { return toAccount; }
    public BigDecimal getAmount() { return amount; }
    public String getChannel() { return channel; }
    public BigDecimal getGst() { return gst; }
    public String getStatus() { return status; }
    public void setStatus(String status) { this.status = status; }
}
