// Interface with STATIC methods — replaces the old TransactionUtils class
package com.bank.gateway.service;

import com.bank.gateway.dto.TransferRequest;
import com.bank.gateway.dto.TransferResponse;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.concurrent.atomic.AtomicLong;

public interface TransactionService {

    // ═══ THE ABSTRACT METHOD — implementations provide channel-specific logic ═══
    TransferResponse transfer(TransferRequest request);

    // ═══ STATIC METHOD 1: Reference number generator ═══
    // Called via: TransactionService.generateTxnId("NEFT")
    // NOT inherited by NeftTransactionService or ImpsTransactionService!
    AtomicLong COUNTER = new AtomicLong(0);  // interface field — implicitly public static final

    static String generateTxnId(String channel) {
        String date = LocalDate.now().format(DateTimeFormatter.ofPattern("yyyyMMdd"));
        long seq = COUNTER.incrementAndGet();
        return channel + "-" + date + "-" + String.format("%06d", seq);
        // e.g., "NEFT-20240115-000001"
    }

    // ═══ STATIC METHOD 2: GST calculator ═══
    static BigDecimal calculateGST(BigDecimal amount) {
        BigDecimal gstRate = new BigDecimal("0.18");  // 18% GST on banking services
        BigDecimal serviceCharge = amount.compareTo(new BigDecimal("10000")) > 0
            ? new BigDecimal("5.90")   // NEFT/RTGS charge for > Rs.10,000
            : new BigDecimal("2.50");
        return serviceCharge.multiply(gstRate).setScale(2, RoundingMode.HALF_UP);
    }

    // ═══ STATIC METHOD 3: Amount validator ═══
    static boolean isValidAmount(BigDecimal amount) {
        return amount != null
            && amount.compareTo(BigDecimal.ONE) >= 0
            && amount.compareTo(new BigDecimal("10000000")) <= 0;
    }

    // ═══ STATIC METHOD 4: Factory — creates appropriate service ═══
    static TransactionService quickTransfer() {
        // Returns a simple lambda implementation for quick transfers
        return request -> {
            String txnId = TransactionService.generateTxnId("QUICK");
            BigDecimal gst = TransactionService.calculateGST(request.amount());
            return new TransferResponse(txnId, "QUICK", request.amount(),
                gst, request.amount().add(gst), "COMPLETED");
        };
    }
}
