// NEFT implementation — CANNOT access interface static methods via class name
package com.bank.gateway.service;

import com.bank.gateway.dto.*;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;

@Service("neftService")
@Slf4j
public class NeftTransactionService implements TransactionService {

    @Override
    public TransferResponse transfer(TransferRequest request) {
        // MUST call via InterfaceName — NOT via "this" or class name
        // NeftTransactionService.generateTxnId("NEFT")  → COMPILE ERROR!
        // this.generateTxnId("NEFT")                    → COMPILE ERROR!
        String txnId = TransactionService.generateTxnId("NEFT");  // (Recommended) CORRECT

        if (!TransactionService.isValidAmount(request.amount())) {
            throw new IllegalArgumentException("Invalid amount: " + request.amount());
        }

        BigDecimal gst = TransactionService.calculateGST(request.amount());
        BigDecimal totalDebit = request.amount().add(gst);

        log.info("[NEFT] Transfer {} → {}: Rs.{} + GST Rs.{} = Rs.{}",
            request.fromAccount(), request.toAccount(),
            request.amount(), gst, totalDebit);

        return new TransferResponse(txnId, "NEFT", request.amount(),
            gst, totalDebit, "PROCESSING");
    }
}
