// IMPS implementation — also calls statics via InterfaceName
package com.bank.gateway.service;

import com.bank.gateway.dto.*;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;

@Service("impsService")
@Slf4j
public class ImpsTransactionService implements TransactionService {

    @Override
    public TransferResponse transfer(TransferRequest request) {
        String txnId = TransactionService.generateTxnId("IMPS");

        if (!TransactionService.isValidAmount(request.amount())) {
            throw new IllegalArgumentException("Invalid amount: " + request.amount());
        }

        BigDecimal gst = TransactionService.calculateGST(request.amount());
        BigDecimal totalDebit = request.amount().add(gst);

        log.info("[IMPS] Instant transfer {} → {}: Rs.{}",
            request.fromAccount(), request.toAccount(), totalDebit);

        return new TransferResponse(txnId, "IMPS", request.amount(),
            gst, totalDebit, "COMPLETED");  // IMPS is instant
    }
}
