package com.bank.gateway.controller;

import com.bank.gateway.dto.*;
import com.bank.gateway.service.TransactionService;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;
import java.util.Map;

@RestController
@RequestMapping("/api/v1/transfer")
public class TransactionController {

    private final TransactionService neftService;
    private final TransactionService impsService;

    public TransactionController(
        @Qualifier("neftService") TransactionService neftService,
        @Qualifier("impsService") TransactionService impsService
    ) {
        this.neftService = neftService;
        this.impsService = impsService;
    }

    @PostMapping("/neft")
    public TransferResponse neft(@RequestBody TransferRequest request) {
        return neftService.transfer(request);
    }

    @PostMapping("/imps")
    public TransferResponse imps(@RequestBody TransferRequest request) {
        return impsService.transfer(request);
    }

    // Static utility — called directly via InterfaceName
    @GetMapping("/validate-amount")
    public Map<String, Object> validateAmount(@RequestParam BigDecimal amount) {
        return Map.of(
            "amount", amount,
            "valid", TransactionService.isValidAmount(amount),
            "gst", TransactionService.calculateGST(amount)
        );
    }

    // Static factory — quick transfer without choosing channel
    @PostMapping("/quick")
    public TransferResponse quick(@RequestBody TransferRequest request) {
        TransactionService quickService = TransactionService.quickTransfer();
        return quickService.transfer(request);
    }
}
