// ─── File: src/test/java/com/bank/gateway/service/StaticMethodTest.java ───
package com.bank.gateway.service;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class StaticMethodTest {

    @Test
    void shouldGenerateUniqueTxnIds() {
        String id1 = TransactionService.generateTxnId("NEFT");
        String id2 = TransactionService.generateTxnId("IMPS");
        assertThat(id1).startsWith("NEFT-");
        assertThat(id2).startsWith("IMPS-");
        assertThat(id1).isNotEqualTo(id2);  // unique sequence
    }

    @Test
    void shouldCalculateGST() {
        BigDecimal gst = TransactionService.calculateGST(new BigDecimal("50000"));
        // Service charge Rs.5.90 × 18% GST = Rs.1.06
        assertThat(gst).isEqualByComparingTo("1.06");
    }

    @Test
    void shouldValidateAmounts() {
        assertThat(TransactionService.isValidAmount(new BigDecimal("1000"))).isTrue();
        assertThat(TransactionService.isValidAmount(new BigDecimal("0"))).isFalse();
        assertThat(TransactionService.isValidAmount(new BigDecimal("20000000"))).isFalse();
        assertThat(TransactionService.isValidAmount(null)).isFalse();
    }

    @Test
    void staticMethodsNotInheritedByImplementingClass() {
        // PROOF: NeftTransactionService does NOT have generateTxnId()
        // NeftTransactionService.generateTxnId("X")  → would NOT compile!
        // Only TransactionService.generateTxnId("X") works.

        // We can verify via reflection:
        assertThatThrownBy(() ->
            NeftTransactionService.class.getDeclaredMethod("generateTxnId", String.class))
            .isInstanceOf(NoSuchMethodException.class);
    }

    @Test
    void staticFactoryCreatesWorkingService() {
        TransactionService quick = TransactionService.quickTransfer();
        var response = quick.transfer(
            new com.bank.gateway.dto.TransferRequest("SAV2001", "CUR3001", new BigDecimal("5000")));
        assertThat(response.channel()).isEqualTo("QUICK");
        assertThat(response.status()).isEqualTo("COMPLETED");
        assertThat(response.txnId()).startsWith("QUICK-");
    }
}
